DO $$
DECLARE
  r record;
  K int; a int; b int; c int; d int; e int; f int;
  ok bool; cnt int := 0;
BEGIN
  FOR K IN -12..12 LOOP
  FOR a IN -2..2 LOOP
  FOR b IN -2..2 LOOP
  FOR c IN -2..2 LOOP
  FOR d IN -2..2 LOOP
    ok := true;
    FOR r IN SELECT * FROM pts LOOP
      IF r.o <> K + a*(r.h%2) + b*(r.w%2) + c*(r.pid%2) + d*(r.para_id%2) THEN
        ok := false; EXIT;
      END IF;
    END LOOP;
    IF ok THEN
      RAISE NOTICE 'FOUND K=% a=% b=% c=% d=%', K,a,b,c,d;
      cnt := cnt + 1;
    END IF;
  END LOOP; END LOOP; END LOOP; END LOOP; END LOOP;
  RAISE NOTICE 'total %', cnt;
END $$;

