DROP TABLE IF EXISTS res;
CREATE TEMP TABLE res(K int, a int, b int, d int, p int, i int);
DO $$
DECLARE
  r record;
  K int; a int; b int; d int; p int; i int;
  ok bool;
BEGIN
  -- model: o = K + a*(h%2) + b*(w%2) + d*(para_id%2) + p*para_id + i*(h%2)*(w%2)
  FOR K IN -12..12 LOOP
  FOR a IN -3..3 LOOP
  FOR b IN -3..3 LOOP
  FOR d IN -3..3 LOOP
  FOR p IN -2..2 LOOP
  FOR i IN -3..3 LOOP
    ok := true;
    FOR r IN SELECT * FROM pts WHERE para_id >= 0 LOOP
      IF r.o <> K + a*(r.h%2) + b*(r.w%2) + d*(r.para_id%2) + p*r.para_id + i*(r.h%2)*(r.w%2) THEN
        ok := false; EXIT;
      END IF;
    END LOOP;
    IF ok THEN
      INSERT INTO res VALUES (K,a,b,d,p,i);
    END IF;
  END LOOP; END LOOP; END LOOP; END LOOP; END LOOP; END LOOP;
END $$;
SELECT * FROM res;

DROP TABLE IF EXISTS res;
CREATE TEMP TABLE res(Xtxt text, M int, K int);
DO $$
DECLARE
  r record;
  M int; K int; X int;
  ok bool;
  combos int[][];
  xt text;
BEGIN
  combos := ARRAY[
    ARRAY[1,1,0,0,0],   -- h + w
    ARRAY[1,1,1,0,0],   -- h + w + para_id
    ARRAY[1,1,0,0,1],   -- h + w + pid
    ARRAY[1,1,1,1,0],   -- ph + h + w + para_id
    ARRAY[1,1,0,1,0],   -- ph + h + w
    ARRAY[0,0,1,1,0],   -- ph + para_id
    ARRAY[0,0,1,1,1],   -- ph + para_id + pid
    ARRAY[1,1,1,0,1],   -- h + w + para_id + pid
    ARRAY[1,1,1,1,1],   -- all
    ARRAY[0,0,0,1,0],   -- para_id
    ARRAY[0,1,0,1,0]    -- ph + para_id? (ph idx2)
  ];
  -- order of coeffs: h, w, para_id, ph, pid
  FOR M IN 2..12 LOOP
  FOR K IN -12..12 LOOP
    FOREACH xt SLICE 0 IN ARRAY combos LOOP
      ok := true;
      FOR r IN SELECT * FROM pts LOOP
        X := xt[1]*r.h + xt[2]*r.w + xt[3]*r.para_id + xt[4]*r.ph + xt[5]*r.pid;
        IF r.o <> (X % M) + K THEN
          ok := false; EXIT;
        END IF;
      END LOOP;
      IF ok THEN
        INSERT INTO res VALUES (array_to_string(xt,','), M, K);
      END IF;
    END LOOP;
  END LOOP; END LOOP;
END $$;
SELECT * FROM res;

DROP TABLE IF EXISTS res;
CREATE TEMP TABLE res(combo text, M int, K int);
DO $$
DECLARE
  r record;
  M int; K int; X int; ci int; cj int;
  ok bool;
  combos int[][] := ARRAY[
    ARRAY[1,1,0,0,0],
    ARRAY[1,1,1,0,0],
    ARRAY[1,1,0,0,1],
    ARRAY[1,1,1,1,0],
    ARRAY[1,1,0,1,0],
    ARRAY[0,0,1,1,0],
    ARRAY[0,0,1,1,1],
    ARRAY[1,1,1,0,1],
    ARRAY[1,1,1,1,1],
    ARRAY[0,0,0,1,0],
    ARRAY[0,1,0,1,0]
  ];
  ctxt text;
BEGIN
  FOR ci IN 1..array_length(combos,1) LOOP
  ctxt := combos[ci][1]||','||combos[ci][2]||','||combos[ci][3]||','||combos[ci][4]||','||combos[ci][5];
  FOR M IN 2..12 LOOP
  FOR K IN -12..12 LOOP
      ok := true;
      FOR r IN SELECT * FROM pts LOOP
        X := combos[ci][1]*r.h + combos[ci][2]*r.w + combos[ci][3]*r.para_id + combos[ci][4]*r.ph + combos[ci][5]*r.pid;
        IF r.o <> (X % M) + K THEN
          ok := false; EXIT;
        END IF;
      END LOOP;
      IF ok THEN
        INSERT INTO res VALUES (ctxt, M, K);
      END IF;
  END LOOP; END LOOP; END LOOP;
END $$;
SELECT * FROM res;

DROP TABLE IF EXISTS res;
CREATE TEMP TABLE res(K int, a int, b int, c int, d int, e int, f int, g int);
DO $$
DECLARE
  r record;
  K int; a int; b int; c int; d int; e int; f int; g int;
  ok bool;
BEGIN
  -- o = K + a*(h%2) + b*(w%2) + c*(pid%2) + d*(para_id%2) + e*(ph%2) + f*((h+w)%2) + g*((h+w+para_id)%2)
  FOR K IN -4..4 LOOP
  FOR a IN -1..1 LOOP
  FOR b IN -1..1 LOOP
  FOR c IN -1..1 LOOP
  FOR d IN -1..1 LOOP
  FOR e IN -1..1 LOOP
  FOR f IN -1..1 LOOP
  FOR g IN -1..1 LOOP
    ok := true;
    FOR r IN SELECT * FROM pts WHERE para_id >= 0 LOOP
      IF r.o <> K + a*(r.h%2) + b*(r.w%2) + c*(r.pid%2) + d*(r.para_id%2) + e*(r.ph%2) + f*((r.h+r.w)%2) + g*((r.h+r.w+r.para_id)%2) THEN
        ok := false; EXIT;
      END IF;
    END LOOP;
    IF ok THEN
      INSERT INTO res VALUES (K,a,b,c,d,e,f,g);
    END IF;
  END LOOP; END LOOP; END LOOP; END LOOP; END LOOP; END LOOP; END LOOP; END LOOP;
END $$;
SELECT * FROM res;

