CREATE TEMP TABLE res(c1 int, c2 int, c3 int, c4 int, c5 int, M int, K int, note text);
DO $$
DECLARE
  r record;
  c1 int; c2 int; c3 int; c4 int; c5 int; M int; K int; X int; ok bool;
BEGIN
  FOR c1 IN -1..1 LOOP
  FOR c2 IN -1..1 LOOP
  FOR c3 IN -1..1 LOOP
  FOR c4 IN -1..1 LOOP
  FOR c5 IN -1..1 LOOP
  FOR M IN 2..20 LOOP
  FOR K IN -20..20 LOOP
    ok := true;
    FOR r IN SELECT * FROM pts LOOP
      X := c1*r.h + c2*r.w + c3*r.para_id + c4*r.ph + c5*r.pid;
      IF r.o <> (X % M) + K THEN ok := false; EXIT; END IF;
    END LOOP;
    IF ok THEN INSERT INTO res VALUES (c1,c2,c3,c4,c5,M,K,'all'); END IF;
    -- also test excluding ex2 (para_id<0)
    ok := true;
    FOR r IN SELECT * FROM pts WHERE para_id >= 0 LOOP
      X := c1*r.h + c2*r.w + c3*r.para_id + c4*r.ph + c5*r.pid;
      IF r.o <> (X % M) + K THEN ok := false; EXIT; END IF;
    END LOOP;
    IF ok THEN INSERT INTO res VALUES (c1,c2,c3,c4,c5,M,K,'ge0'); END IF;
  END LOOP; END LOOP; END LOOP; END LOOP; END LOOP; END LOOP; END LOOP;
END $$;
